solution.solution.c:
#include <stdarg.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int compare_ints(const void *a, const void *b)
{
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

void sort_ints(int *values, size_t count)
{
    qsort(values, count, sizeof values[0], compare_ints);
}

const int *find_sorted(const int *values, size_t count, int key)
{
    return bsearch(&key, values, count, sizeof values[0], compare_ints);
}

int sum_all(int count, ...)
{
    va_list args;
    va_start(args, count);
    int total = 0;
    for (int i = 0; i < count; i++) total += va_arg(args, int);
    va_end(args);
    return total;
}

void format_date(char *out, size_t size, int year, int month, int day)
{
    snprintf(out, size, "%04d-%02d-%02d", year, month, day);
}

void remove_at(char *s, size_t index)
{
    size_t length = strlen(s);
    if (index >= length) return;
    memmove(s + index, s + index + 1, length - index);
}

unitTests:
TEST("sorting") { int v[] = {9, -1, 4, 4, 0}; sort_ints(v, 5); CHECK_EQ(v[0], -1); CHECK_EQ(v[1], 0); CHECK_EQ(v[2], 4); CHECK_EQ(v[3], 4); CHECK_EQ(v[4], 9); }
TEST("binary search") { int v[] = {2, 3, 5, 7, 11, 13}; CHECK(find_sorted(v, 6, 7) == v + 3); CHECK(find_sorted(v, 6, 2) == v); CHECK(find_sorted(v, 6, 13) == v + 5); CHECK(find_sorted(v, 6, 6) == NULL); CHECK(find_sorted(v, 0, 2) == NULL); }
TEST("any number of arguments") { CHECK_EQ(sum_all(0), 0); CHECK_EQ(sum_all(1, 5), 5); CHECK_EQ(sum_all(4, 10, 20, 30, 40), 100); CHECK_EQ(sum_all(3, -1, -2, 3), 0); }
TEST("formatting dates") { char d[16]; format_date(d, sizeof d, 2024, 3, 7); CHECK_STR(d, "2024-03-07"); format_date(d, sizeof d, 1969, 12, 31); CHECK_STR(d, "1969-12-31"); format_date(d, 5, 2024, 3, 7); CHECK_STR(d, "2024"); }
TEST("removing a character") { char s[] = "abcdef"; remove_at(s, 2); CHECK_STR(s, "abdef"); remove_at(s, 0); CHECK_STR(s, "bdef"); remove_at(s, 3); CHECK_STR(s, "bde"); remove_at(s, 10); CHECK_STR(s, "bde"); }

